import{_ as e,o as t,c as a,ag as s}from"./chunks/framework.DyZQ0-wY.js";const p=JSON.parse('{"title":"Loading songs","description":"","frontmatter":{},"headers":[],"relativePath":"footnotes/loading-songs.md","filePath":"footnotes/loading-songs.md"}'),n={name:"footnotes/loading-songs.md"};function r(i,o,h,d,l,c){return t(),a("div",null,[...o[0]||(o[0]=[s('<h1 id="loading-songs" tabindex="-1">Loading songs <a class="header-anchor" href="#loading-songs" aria-label="Permalink to &quot;Loading songs&quot;">​</a></h1><p>Footnotes plays StepMania simfiles: a <code>.sm</code> or <code>.ssc</code> file together with the song&#39;s music, usually an <code>.ogg</code> or <code>.mp3</code> file in the same folder. You can try the demo song, load a song from a link, or open a song folder from your computer.</p><h2 id="the-demo-song" tabindex="-1">The demo song <a class="header-anchor" href="#the-demo-song" aria-label="Permalink to &quot;The demo song&quot;">​</a></h2><p>The <a href="https://chihduo.github.io/footnotes/" target="_blank" rel="noreferrer">Footnotes home page</a> has a one-minute demo song with Beginner, Easy and Medium charts. <strong>Try the demo song</strong> opens the Beginner chart, and the <strong>Try the demo</strong> card has a button for each chart. The song was made for Footnotes, so you can share it freely.</p><h2 id="from-a-link" tabindex="-1">From a link <a class="header-anchor" href="#from-a-link" aria-label="Permalink to &quot;From a link&quot;">​</a></h2><p>Paste a link to a <code>.sm</code> or <code>.ssc</code> file into <strong>From a link</strong> on the home page and press <strong>Find charts</strong>. Footnotes lists the charts in the file in a pop-up, and you pick the one you want to practice.</p><p>For a link to work:</p><ul><li>It has to point straight to the <code>.sm</code> or <code>.ssc</code> file, not to a page that shows it.</li><li>The music file has to be next to the simfile, at the path the simfile names.</li><li>The site hosting the files has to let other pages read them.</li></ul><p>GitHub works well: put the song folder in a public repository, open the simfile, and copy the link of its <strong>Raw</strong> button (it starts with <code>https://raw.githubusercontent.com/</code>). Most file-sharing pages, such as Google Drive or Dropbox share links, don&#39;t work, because they link to a preview page instead of the file.</p><h2 id="from-your-computer" tabindex="-1">From your computer <a class="header-anchor" href="#from-your-computer" aria-label="Permalink to &quot;From your computer&quot;">​</a></h2><ol><li>On the home page, choose <strong>Open a song folder</strong>.</li><li>Choose <strong>Import a song folder</strong>, then <strong>Upload folder</strong>, and select the folder that holds the simfile and its music.</li><li>Open the uploaded folder, click the <code>.sm</code> or <code>.ssc</code> file, and press <strong>Select</strong>.</li></ol><p>Uploaded songs stay in your browser, so you only upload a song once. The next time, pick it from the file list or from <strong>Recently Opened</strong>.</p><h2 id="choosing-a-chart" tabindex="-1">Choosing a chart <a class="header-anchor" href="#choosing-a-chart" aria-label="Permalink to &quot;Choosing a chart&quot;">​</a></h2><p>Songs usually have several charts, from Beginner to Challenge. The home page lists them all when you load a song from a link.</p><p>While practicing, press <strong>Charts</strong> in the bottom bar, or <kbd>Ctrl</kbd>+<kbd>Shift</kbd>+<kbd>O</kbd> (<kbd>⌘</kbd>+<kbd>Shift</kbd>+<kbd>O</kbd> on a Mac), to open the chart list. Pick a game type at the top, then click a chart to switch to it.</p><p>The dancing bot works with <strong>dance single</strong>, <strong>dance double</strong>, <strong>pump single</strong> and <strong>pump double</strong> charts.</p><h2 id="sharing-a-song" tabindex="-1">Sharing a song <a class="header-anchor" href="#sharing-a-song" aria-label="Permalink to &quot;Sharing a song&quot;">​</a></h2><p>To send someone a song, share one of these links. Replace <code>&lt;link&gt;</code> with the link to the simfile.</p><table tabindex="0"><thead><tr><th>Link</th><th>Opens</th></tr></thead><tbody><tr><td><code>https://chihduo.github.io/footnotes/?song=&lt;link&gt;</code></td><td>The home page, with the song&#39;s charts listed</td></tr><tr><td><code>https://chihduo.github.io/footnotes/app/?url=&lt;link&gt;&amp;chartType=dance-single&amp;chartIndex=0&amp;flags=D</code></td><td>One chart, straight in practice mode</td></tr></tbody></table><p><code>chartIndex</code> counts the charts of that game type from <code>0</code>, in order from Beginner to Challenge. The easiest way to get one of these links is to pick a chart on the home page and copy the address of the page that opens.</p>',20)])])}const m=e(n,[["render",r]]);export{p as __pageData,m as default};
